def build_agent(sandbox):
    beam_density = 5.0  # kg/m²
    beam_width = 1.0    # Max width for full coverage in x
    beam_height = 0.08  # Minimum height to reduce mass
    beam_y_positions = [2.41, 1.92, 1.76]  # All within build zone y limits

    beams = []
    for y in beam_y_positions:
        beam = sandbox.add_static_beam(
            x=6.05,  # Centered in x = [5.20, 6.90]
            y=y,
            width=beam_width,
            height=beam_height,
            density=beam_density
        )
        sandbox.set_material_properties(beam, restitution=0.0)
        beams.append(beam)

    return beams[0]

def agent_action(sandbox, agent_body, step_count):
    NUDGE_PERIOD = 32
    NUDGE_FORCE_SMALL = 10.0
    NUDGE_FORCE_MEDIUM = 8.0

    if step_count % NUDGE_PERIOD != 0:
        return

    for p in sandbox.get_particles_small():
        if p.active and p.position.y > 1.92:
            sandbox.apply_force(p, (0, -NUDGE_FORCE_SMALL))

    for p in sandbox.get_particles_medium():
        if p.active and p.position.y > 2.52:
            sandbox.apply_force(p, (0, -NUDGE_FORCE_MEDIUM))
